// Package gen writes the comparison module: one shared schema, one shared
// set of Go structs, and an implementation for each engine over them.
//
// Both engines are bound to the same structs and configured so that every
// composite field goes through a resolver. Without that they measure
// different work: gqlgen serves composite fields from struct data by default,
// where graphql-go always resolves them.
package gen

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

// EntityName is the GraphQL type name of the i-th entity, matching the SDL
// generated by benchmarks/buildbench.
func EntityName(i int) string { return fmt.Sprintf("Entity%03d", i) }

func lowerFirst(s string) string {
	if s == "" {
		return s
	}
	return strings.ToLower(s[:1]) + s[1:]
}

// rowsPerEntity is how many records each entity type holds. Small enough to
// keep generation cheap, large enough that a connection query does real work.
const rowsPerEntity = 20

// writeShared emits the structs both engines bind to, plus a fixed dataset.
// The structs carry leaf fields only; every composite field is a resolver on
// both sides, so neither engine can serve one from struct data.
func writeShared(root string, n int) error {
	var b strings.Builder
	b.WriteString(`// Code generated by compare/internal/gen. DO NOT EDIT.

// Package shared holds the Go types both engines bind to, and a fixed
// dataset served by both, so the comparison measures the engines rather
// than two different data layers.
package shared

import (
	"strconv"
	"time"
)

// Epoch keeps generated timestamps identical between runs.
var Epoch = time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC)

type PageInfo struct {
	HasNextPage     bool
	HasPreviousPage bool
	StartCursor     *string
	EndCursor       *string
}

func cursor(i int) string { return "cursor:" + strconv.Itoa(i) }
`)

	for i := range n {
		name := EntityName(i)
		owner := EntityName((i + 1) % n)
		child := EntityName((i + 2) % n)
		fmt.Fprintf(&b, `
type %[1]s struct {
	ID          string
	Name        string
	Description *string
	CreatedAt   time.Time
	UpdatedAt   *time.Time
	Active      bool
	Score       int
	Ratio       float64
	Tags        []string

	ownerIdx int
}

// IsNode marks %[1]s as implementing the Node interface. gqlgen requires the
// marker method on the bound type; graphql-go resolves the interface from the
// dynamic Go type and ignores it.
func (%[1]s) IsNode() {}

// GetID satisfies the field getter gqlgen generates for interface fields.
func (v %[1]s) GetID() string { return v.ID }

type %[1]sConnection struct {
	TotalCount int
	Nodes      []*%[1]s
}

type %[1]sEdge struct {
	Cursor string
	Node   *%[1]s
}

var (
	all%[1]s  []*%[1]s
	by%[1]sID = map[string]*%[1]s{}
)

// Get%[1]s returns the record with this id, or nil.
func Get%[1]s(id string) *%[1]s { return by%[1]sID[id] }

// List%[1]s returns every record, in a stable order.
func List%[1]s() []*%[1]s { return all%[1]s }

// Owner%[1]s is the linked %[2]s of a %[1]s.
func Owner%[1]s(v *%[1]s) *%[2]s {
	if v == nil {
		return nil
	}
	return all%[2]s[v.ownerIdx%%len(all%[2]s)]
}

// Children%[1]s is the %[3]s connection hanging off a %[1]s.
func Children%[1]s(v *%[1]s, first int) *%[3]sConnection {
	rows := all%[3]s
	if first > 0 && first < len(rows) {
		rows = rows[:first]
	}
	return &%[3]sConnection{TotalCount: len(all%[3]s), Nodes: rows}
}

// Edges%[1]s materialises the edges of a connection.
func Edges%[1]s(c *%[1]sConnection) []*%[1]sEdge {
	out := make([]*%[1]sEdge, len(c.Nodes))
	for i, nd := range c.Nodes {
		out[i] = &%[1]sEdge{Cursor: cursor(i), Node: nd}
	}
	return out
}

// PageInfo%[1]s describes a connection's page.
func PageInfo%[1]s(c *%[1]sConnection) *PageInfo {
	pi := &PageInfo{HasNextPage: len(c.Nodes) < c.TotalCount}
	if len(c.Nodes) > 0 {
		s, e := cursor(0), cursor(len(c.Nodes)-1)
		pi.StartCursor, pi.EndCursor = &s, &e
	}
	return pi
}

// Conn%[1]s is the top-level connection over every %[1]s.
func Conn%[1]s(first int) *%[1]sConnection {
	rows := all%[1]s
	if first > 0 && first < len(rows) {
		rows = rows[:first]
	}
	return &%[1]sConnection{TotalCount: len(all%[1]s), Nodes: rows}
}

func init() {
	all%[1]s = make([]*%[1]s, %[4]d)
	for i := range all%[1]s {
		id := strconv.Itoa(i)
		desc := "description of %[1]s " + id
		up := Epoch.Add(time.Duration(i) * time.Hour)
		v := &%[1]s{
			ID:          id,
			Name:        "%[1]s-" + id,
			Description: &desc,
			CreatedAt:   Epoch,
			UpdatedAt:   &up,
			Active:      i%%2 == 0,
			Score:       i * 3,
			Ratio:       float64(i) / 2,
			Tags:        []string{"a", "b"},
			ownerIdx:    i,
		}
		all%[1]s[i] = v
		by%[1]sID[id] = v
	}
}
`, name, owner, child, rowsPerEntity)
	}

	dir := filepath.Join(root, "shared")
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return err
	}
	return os.WriteFile(filepath.Join(dir, "shared.go"), []byte(b.String()), 0o644)
}
